create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.BESCH_FAKTURA_LGORT_WG_WUP_1 cluster by (dat_faktura)(
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_1 im DWH',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup_1 ID wird verwendet für Beziehung Lager zu Verteilzentrum',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	LAGERORT_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Dieses Feld referenziert die DWH Tabelle Lagerort.',
	WG_ID NUMBER(38,0) NOT NULL COMMENT 'ID der Warengruppe',
	FAKTURAART_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Klassifiziert verschiedene Arten von Fakturabelegen, die eine_1 unterschiedliche Verarbeitung durch das System erfordern.',
	DAT_FAKTURA DATE NOT NULL COMMENT 'Hier ist abhängig von der Fakturaart entweder das Fakturadatum oder das Datum der Leistungserstellung enthalten',
	DAT_ERSTELLUNG DATE NOT NULL COMMENT 'Das Feld enthält das Erstelldatum des Datensatzes',
	DAT_LEIST_ERSTELLUNG DATE NOT NULL COMMENT 'Datum der Leistungserstellung.     \n            ',
	ARTHIERTYP_ID NUMBER(38,0) NOT NULL COMMENT 'Artikel_1 - Hierarchie - Typ - ID: kennzeichnet, ob es sich um eine_1 Hierarchie mit zwei- oder dreistelligen Warengruppen  handelt',
	AUFTRAGGEBER_ID VARCHAR(10) NOT NULL COMMENT 'Kundennummer des Auftaggebers. Noch keine Referenz zu einer bestehenden DWH Tabelle möglich (SAP Quellel KNA1_1)',
	BESTELLART_ID VARCHAR(4) COLLATE 'en-ci' COMMENT 'ID der Bestellart',
	DAT_PREISFINDUNG DATE COMMENT 'Datum für Preisfindung und Währungskurs, kann vom Fakturadatum abweichen',
	AUFTRAG_GRUND_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' COMMENT 'Grund für die Erstellung eines Verkaufsbelegs',
	VERRECHNUNG_BETRAG NUMBER(18,2) WITH MASKING POLICY #unknown_policy COMMENT 'Verrechnungswert einer Position in einem lieferbezogenen Fakturabeleg. Der Verrechnungswert wird bei der Buchung des Warenausgangs ermittelt.Format decimal(18,2). Aus wavwr',
	ZWSUM_1_BETRAG NUMBER(18,2) WITH MASKING POLICY #unknown_policy COMMENT 'Konditionszwischensumme 1 aus dem Kalkulationsschema. Dies entspricht dem End Betrag des Schemas. Format decimal(18,2)',
	ZWSUM_2_BETRAG NUMBER(18,2) COMMENT 'Konditionszwischensumme 2 aus dem Kalkulationsschema. Dies entspricht dem Verkaufspreis. Format decimal(18,2)',
	ZWSUM_3_BETRAG NUMBER(18,2) WITH MASKING POLICY #unknown_policy COMMENT 'Konditionszwischensumme 3 aus dem Kalkulationsschema. Dies entspricht dem Einkaufspreis Netto bei Reklamationen (Einkaufspreis netto  bzw. EK-Aktion_1 netto vermindert um die Reklapauschale). Format decimal(18,2)',
	ZWSUM_4_BETRAG NUMBER(18,2) WITH MASKING POLICY #unknown_policy COMMENT 'Konditionszwischensumme 4 aus dem Kalkulationsschema. Dies entspricht dem Lagerwert bei Reklamationen (Reklapauschale) Format decimal(18,2)',
	ZWSUM_5_BETRAG NUMBER(18,2) COMMENT 'Konditionszwischensumme 5 aus dem Kalkulationsschema. Dies entspricht dem Verkaufswert bei Reklamationen. Format decimal(18,2)',
	ZWSUM_6_BETRAG NUMBER(18,2) WITH MASKING POLICY #unknown_policy COMMENT 'Konditionszwischensumme 6 aus dem Kalkulationsschema. Dies entspricht dem Wert der Logistikvergütung für diese Position. Format decimal(18,2)',
	ZWSUM_8_BETRAG NUMBER(18,2) COMMENT 'Enthält den Rabattbetrag  bezogen auf den VK_1 im Fall von teilkostenloser Lieferung. Format decimal(18,2)',
	ZWSUM_9_BETRAG NUMBER(18,2) WITH MASKING POLICY #unknown_policy COMMENT 'Enthält den Rabattbetrag - bezogen auf den EK - im Fall von teilkostenloser Lieferung. Format decimal(18,2) Compress CD-47-AD-36-C7-B7-B2-2A-FF-C7-61-09-CC-15-E3-DD',
	VK_NETTO_BETRAG NUMBER(18,2) COMMENT 'zwsum_2_betrag reduziert um MWSt-Betrag',
	VK_NETTO_REKL_TKL_BETRAG NUMBER(18,2) COMMENT 'Summe aus zwsum2 + zwsum5 + zwsum8, reduziert um die MWSt',
	MENGE_FAKTURA_KOLLI NUMBER(18,3) COMMENT 'Dieses Feld enthält die Menge in der Kollimengeneinheit. Der gültige Umrechnungsfaktor wird aus der DWH Tabelle art_umrechnung_faktor_per_1 ermittelt',
	MENGE_FAKTURA_PALETTE NUMBER(18,3) COMMENT 'Dieses Feld enthält die Menge in der Palettenmengeneinheit. Der erforderliche Umrechnungsfaktor wird aus den DWH Tabellen art_vorschlagswert_per_1 und art_umrechnung_faktor_per_1 ermittelt.',
	MENGE_FAKTURA_BME NUMBER(18,3) COMMENT 'Fakturierte Menge der Fakturabelegposition.',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	WRG_ID VARCHAR(3) COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR',
	constraint PK_BESCH_FAKTURA_LGORT_WG_WUP primary key (MANDANT_ID, WUP_ID, NB_ID, LAGERORT_ID, WG_ID, FAKTURAART_ID, DAT_FAKTURA, DAT_ERSTELLUNG, DAT_LEIST_ERSTELLUNG, ARTHIERTYP_ID, AUFTRAGGEBER_ID)
)COMMENT='TP408_LVS - Diese Tabelle enthält die nach Warengruppe, VZ und Lagerort aggregierten Fakturabelege.'
;
